INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish6', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3340,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort bogstav: 'Vi kørte mod nord til skagen og mod syd til Ribe.'?","o":["kørte","nord","syd","skagen"],"a":"skagen","r":"Skagen er et stednavn. Verdenshjørner som nord og syd skrives med lille, når de bare angiver en retning."},
{"l":3361,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tænder er dækket af emalje, som er det hårdeste stof i kroppen. Men når du spiser sukker, laver bakterier i munden syre, og syren kan langsomt ødelægge emaljen. Derfor er det vigtigt at børste tænder morgen og aften og ikke spise sødt hele dagen.' Hvorfor er det dårligere at spise slik hele dagen end kun én gang?","o":["Fordi syren så angriber tænderne igen og igen","Fordi tænderne bliver større af at tygge meget","Fordi emalje kun kan tåle sukker om morgenen","Fordi bakterierne i munden forsvinder af slik"],"a":"Fordi syren så angriber tænderne igen og igen","r":"Teksten siger, at sukker giver syre, og at syren ødelægger emaljen. Ofte sukker betyder altså ofte syre."},
{"l":3379,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rundetaarn i København blev bygget af Christian 4. og stod færdigt i 1642. Inde i tårnet er der ikke trapper, men en lang, snoet gang. Øverst i tårnet ligger et observatorium, hvor man kan kigge på stjernerne.' Hvilket spørgsmål kan teksten IKKE svare på?","o":["Hvem fik bygget Rundetaarn?","Hvad kostede det at bygge tårnet?","Hvad er der øverst i tårnet?","Hvornår stod tårnet færdigt?"],"a":"Hvad kostede det at bygge tårnet?","r":"Teksten nævner intet om prisen. De andre oplysninger står der."},
{"l":3400,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør den, der 'stikker hovedet i busken'?","o":["Leder efter noget tabt i haven","Gemmer sig for sine venner for sjov","Lader, som om et problem ikke findes","Holder sig varm i dårligt vejr"],"a":"Lader, som om et problem ikke findes","r":"Vendingen bruges om dem, der ikke vil se et problem i øjnene. Problemet bliver ikke væk af den grund."},
{"l":3421,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt 'at give' i datid: 'Læreren ___ os lidt ekstra tid til prøven i fredags.'","o":["giver","givet","give","gav"],"a":"gav","r":"'I fredags' viser, at det er sket. Datid af 'at give' er 'gav'."},
{"l":3443,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er rigtigt? 'Er I ___ på, at vi skal til venstre?'","o":["sikre","sikkere","sikkre","sikere"],"a":"sikre","r":"I flertal falder e'et væk fra grundformen, og så er der kun ét k tilbage foran r."},
{"l":3465,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Hun ___ allerede spist, da vi kom.'","o":["har","havde","have","haft"],"a":"havde","r":"'Da vi kom' står i datid, og hun spiste før det. Så skal der bruges førdatid med 'havde'."},
{"l":3482,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket af disse dyr hører til 'padderne'?","o":["snog","stær","skrubtudse","spidsmus"],"a":"skrubtudse","r":"Padder lever først i vand som haletudser og senere også på land. Snogen er et krybdyr, stæren en fugl."},
{"l":3504,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rasmus tog en dyb indånding og bankede på. Inde på kontoret sad skolelederen. Han lagde bolden, der havde knust ruden, på bordet. Der var ingen, der havde set ham, men han kunne ikke holde ud at sove endnu en nat med hemmeligheden.' Hvorfor går Rasmus til skolelederen?","o":["Han vil have sin bold tilbage af skolelederen","Han vil give skylden for ruden til en anden elev","Han er blevet opdaget af en, der så ham","Han kan ikke holde ud at gå med hemmeligheden"],"a":"Han kan ikke holde ud at gå med hemmeligheden","r":"Ingen har set ham, så han behøver ikke at gå derind. Men han kan ikke sove med hemmeligheden, for han har dårlig samvittighed."},
{"l":3520,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Naboen har to ___ og en datter.'","o":["sønner","søner","sønder","søns"],"a":"sønner","r":"I flertal fordobles n'et, fordi ø'et er kort."},
{"l":3542,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'atmosfæren'?","o":["den varme kerne inde i Jorden","laget af luft rundt om Jorden","alle de have, der findes på Jorden","den is, der dækker Jordens poler"],"a":"laget af luft rundt om Jorden","r":"Atmosfæren består af luftarter, blandt andet ilt. Den giver os luft at ånde i og beskytter os mod noget af solens stråling."},
{"l":3564,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordsleddet: 'Emma venter ved busstoppestedet.'","o":["Emma","venter","ved busstoppestedet","Emma venter ved"],"a":"ved busstoppestedet","r":"Leddet begynder med forholdsordet 'ved' og fortsætter med det navneord, det hører sammen med."},
{"l":3580,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'sam-' i ord som 'samarbejde' og 'samtale'?","o":["igen","imod","alene","sammen"],"a":"sammen","r":"Når man samarbejder, arbejder man sammen med andre, og i en samtale taler man sammen."},
{"l":3600,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fiskerne på kysten kalder fyrtårnet Vandreren, fordi det er flyttet to gange, begge gange længere ind i land. Havet tog nemlig klinten under det.' Hvad er årsagen til, at fyrtårnet er flyttet?","o":["Havet har gnavet jorden væk under det","Fiskerne ville have det tættere på byen","Det skulle kunne ses længere ude på havet","Det blev for gammelt til at stå på klinten"],"a":"Havet har gnavet jorden væk under det","r":"'Havet tog klinten under det' er et billede på, at kysten blev slidt væk. Navnet Vandreren er bare et kælenavn for flytningerne."},
{"l":3619,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige flertalsform: 'I eventyret havde kongen tre ___.'","o":["døttre","døtre","døtter","datre"],"a":"døtre","r":"Ental er 'datter'. I flertal skifter a til ø, og der er kun ét t."},
{"l":3640,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige, at noget 'koster det hvide ud af øjnene'?","o":["Det gør meget ondt","Det er meget farligt","Det er meget dyrt","Det går meget hurtigt"],"a":"Det er meget dyrt","r":"Vendingen er en kraftig overdrivelse: Prisen er så høj, at man næsten må betale med det hvide i sine øjne."},
{"l":3657,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'De fleste dyr har farver, der skjuler dem. Sneharen er grå om sommeren og hvid om vinteren. Men nogle dyr vil gerne ses. Den gulsorte hveps viser med sine farver: Pas på, jeg stikker! Fugle lærer hurtigt at holde sig væk.' Hvordan hjælper hvepsens farver den?","o":["De holder den varm om vinteren","De gør det let at finde blomster","De skjuler den i det grønne","De viser fjender, at den stikker"],"a":"De viser fjender, at den stikker","r":"Teksten skelner mellem farver, der skjuler, og farver, der advarer. Hvepsen hører til den sidste slags."},
{"l":3677,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hunden snuser 'mistænksomt' til maden. Hvad fortæller ordet om hunden?","o":["Den stoler ikke helt på maden","Den er meget sulten og glad","Den er træt og vil hellere sove","Den vil gerne dele med de andre"],"a":"Den stoler ikke helt på maden","r":"Den mistænksomme tror, at der kan være noget galt. Hunden er altså på vagt."},
{"l":3696,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et talord: 'Der kom hundrede gæster til festen.'","o":["gæster","hundrede","festen","kom"],"a":"hundrede","r":"'Hundrede' fortæller antallet af gæster, så det er et talord."},
{"l":3718,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg rigtigt: 'Læreren ___ alle stilene i weekenden.'","o":["retede","retted","rettede","rettet"],"a":"rettede","r":"Dobbelt t, fordi e'et er kort, og datid ender her på -ede."},
{"l":3739,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Hvor hun bor ved jeg ikke.'?","o":["hun","ved","jeg","bor"],"a":"bor","r":"'Hvor hun bor' er en ledsætning, der står først. Hovedsætningen er 'ved jeg ikke'."},
{"l":3758,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Elias er Dansker og bor på Fyn i Odense.'?","o":["Dansker","Elias","Fyn","Odense"],"a":"Dansker","r":"Ord for folk fra et land skrives med lille, også selv om landets navn får stort bogstav."},
{"l":3777,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Kommaet står forkert i én af sætningerne om kaninen. Hvilken?","o":["Kaninen spiste gulerødder, salat og hø.","Kaninen spiste, gulerødder og salat.","Da kaninen var mæt, sov den.","Efter maden sov kaninen."],"a":"Kaninen spiste, gulerødder og salat.","r":"Kommaet må ikke skille 'spiste' fra det, kaninen spiste. Opremsningen består her kun af to ting bundet sammen med 'og'."},
{"l":3796,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Når man har lånt en bog skal man aflevere den igen.'?","o":["lånt","skal","bog","aflevere"],"a":"bog","r":"'Når man har lånt en bog' er en ledsætning, der står først. Hovedsætningen begynder med 'skal'."},
{"l":3817,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Holdet fra Aabyskolen har vundet en præmie for en opfindelse, der skal hjælpe ældre. Det er en lille lampe, der tænder af sig selv, når man står ud af sengen om natten. – Min mormor faldt om natten, så jeg vidste, det var et rigtigt problem, siger 12-årige Maja.' Hvor fik Maja idéen fra?","o":["Fra en konkurrence om lamper","Fra en lærer på Aabyskolen","Fra en lampe hun havde set i en butik","Fra noget, der var sket i hendes familie"],"a":"Fra noget, der var sket i hendes familie","r":"Maja fortæller, at hendes mormor faldt. Det viste hende, at der var et problem at løse."},
{"l":3835,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fra 1. september skal alle cykler ved skolen stå i de nye stativer ved hovedindgangen. De gamle stativer ved boldbanen bliver fjernet, fordi de er rustne. Elever, der har hængelås, kan få den flyttet af pedellen. Tak for hjælpen.' Hvad skal eleverne gøre efter den 1. september?","o":["Parkere ved hovedindgangen","Stille cyklen ved boldbanen","Fjerne de gamle stativer selv","Købe en ny hængelås til cyklen"],"a":"Parkere ved hovedindgangen","r":"Der står, at alle cykler skal stå ved hovedindgangen. Det er ikke eleverne, der skal fjerne stativerne."},
{"l":3857,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mangler: 'Hvis du ikke afleverer din stil, må du selv tage ___ af det.'","o":["begyndelsen","konsekvensen","udsigten","overskriften"],"a":"konsekvensen","r":"En konsekvens er det, der følger af en handling. Tager man konsekvensen, accepterer man følgerne af det, man har gjort."},
{"l":3872,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå til sidst: 'Jeg ved ikke, hvem der har taget min lineal'?","o":["spørgsmålstegn","udråbstegn","punktum","kolon"],"a":"punktum","r":"Selv om ordet 'hvem' står i sætningen, er det ikke et spørgsmål. Sætningen fortæller, hvad jeg ikke ved."},
{"l":3895,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Nikolaj siger: 'Jeg har sagt det en million gange!' Hvad gør han?","o":["Han undskylder","Han spørger","Han tæller","Han overdriver"],"a":"Han overdriver","r":"Han har ikke sagt det en million gange. At overdrive er at gøre noget større, end det er, for at understrege sin mening."},
{"l":3916,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bævere bygger dæmninger af grene og mudder. Dæmningen stemmer vandet op, så der opstår en sø. I søen bygger bæveren sin hytte med indgang under vandet. På den måde kan rovdyr ikke så let komme ind.' Hvad er meningen med dæmningen for bæveren?","o":["Den skaber en sø, der beskytter dens hytte","Den giver bæveren et sted at spise grene","Den holder alle fisk væk fra dens hytte","Den er en bro, bæveren kan gå over søen på"],"a":"Den skaber en sø, der beskytter dens hytte","r":"Dæmningen giver en sø, og i søen kan hytten have sin indgang under vandet. Så kan rovdyr ikke så let komme ind."},
{"l":3934,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jonathan havde fået et nyt skateboard. Han kørte stolt ned ad bakken, mens alle så på. Så ramte han en sten og fløj på maven. Han rejste sig hurtigt og børstede knæene af. – Det var bare en test! råbte han.' Hvorfor råber Jonathan det?","o":["Han har faktisk øvet sig på at falde","Han vil ikke have, at det skal se pinligt ud","Han vil have de andre til at prøve","Han vil have hjælp til sine knæ"],"a":"Han vil ikke have, at det skal se pinligt ud","r":"Jonathan var stolt, og alle så ham falde. Han prøver at gøre det til en spøg, så det ikke bliver så pinligt."},
{"l":3952,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver sommer, når vandet i Vesterled Sø bliver varmt, kommer der blågrønne alger. De kan være giftige for både mennesker og hunde. Kommunen sætter skilte op, når der er for mange. Sidste år var søen lukket for badning i tre uger. Læg mærke til skiltene, inden du går i vandet.' Hvorfor er teksten skrevet?","o":["At forklare, hvordan alger får deres farve","At fortælle, hvornår søen er bedst","At advare folk mod giftige alger i søen","At få kommunen til at sætte skilte op"],"a":"At advare folk mod giftige alger i søen","r":"Teksten slutter med at bede dig om at se på skiltene, så du ikke bliver syg af algerne."},
{"l":3971,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket spørgende stedord passer: '___ bog læser du?'","o":["Hvilket","Hvem","Hvad","Hvilken"],"a":"Hvilken","r":"Det hedder en bog, så det skal være 'hvilken'. 'Hvilket' bruger man foran et-ord."},
{"l":3993,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Vi spiste ___, fordi der ikke var nogen stole.'","o":["stående","ståene","ståenne","stånde"],"a":"stående","r":"Også korte udsagnsord får hele endelsen -ende i lang tillægsform."},
{"l":4015,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning om skovturen har ordene i rigtig rækkefølge?","o":["Vi tager på skovtur, hvis regner det ikke.","Vi tager på skovtur, hvis det ikke regner.","Vi tager på skovtur, hvis det regner ikke.","Vi tager på skovtur, hvis ikke regner det."],"a":"Vi tager på skovtur, hvis det ikke regner.","r":"I en ledsætning står 'ikke' før udsagnsordet, og grundleddet står lige efter bindeordet."},
{"l":4037,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ordet 'bord' er konkret, fordi man kan røre ved tingen. Hvad er ordet 'frihed' så?","o":["udenlandsk","forældet","abstrakt","forkortet"],"a":"abstrakt","r":"Abstrakte ord betegner noget, man ikke kan røre eller se, for eksempel tanker og følelser. Abstrakt er det modsatte af konkret."},
{"l":4059,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En lille by ude på landet: Hvordan staves ordet for den?","o":["landby","lansby","landsbye","landsby"],"a":"landsby","r":"Ordet er sammensat af 'land' og 'by' med et fuge-s imellem. D'et skal med, selvom det ikke høres."},
{"l":4077,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Interview med 12-årige Tilde, der har skrevet en bog. Hvorfor begyndte du? – Min farfar fortalte mig om sin barndom, og jeg var bange for, at det ville blive glemt. Var det svært? – Ja, jeg måtte skrive det første kapitel om fem gange. Hvad er dit råd til andre? – Lad være med at slette noget, før du har læst det dagen efter.' Hvorfor skrev Tilde bogen?","o":["Hun ville bevare farfars historier","Hun ville gerne blive rig og kendt","Hun ville vinde en stor konkurrence","Hun ville give råd til andre børn"],"a":"Hun ville bevare farfars historier","r":"Hun siger, at hun var bange for, at det, farfar fortalte, ville blive glemt. Rådet til andre kommer først til sidst i interviewet."},
{"l":4095,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I 1902 fandt en landmand på Sjælland en bronzehest på et lille vognstel, mens han pløjede sin mose. Hesten trækker en stor skive, der på den ene side er dækket af guld. Forskere mener, at figuren viser, hvordan folk i bronzealderen forestillede sig, at solen rejste over himlen. Den kaldes Solvognen.' Hvad er forskernes tolkning af figuren?","o":["At den er legetøj til et barn","At den viser solens rejse hen over himlen","At den blev brugt til at pløje i mosen","At den er en model af landmandens hest"],"a":"At den viser solens rejse hen over himlen","r":"Der står 'forskere mener', så det er en tolkning af, hvad figuren betyder."},
{"l":4114,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Pigerne har ___ hele timen.'","o":["snakkede","snakker","snakket","snakke"],"a":"snakket","r":"Efter 'har' skal der stå tillægsform på -et. Datiden 'snakkede' lyder næsten ens, men kan ikke stå efter 'har'."},
{"l":4136,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at skære' passer: 'Far har ___ brødet i skiver.'","o":["skar","skærer","skære","skåret"],"a":"skåret","r":"Tillægsformen af 'at skære' er 'skåret'. 'Skar' er datid."},
{"l":4157,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Mens læreren skrev opgaven på tavlen tegnede Viktor en hest i sit hæfte.'?","o":["tavlen","skrev","tegnede","hest"],"a":"tavlen","r":"Ledsætningen slutter efter 'tavlen'. Hovedsætningen begynder med udsagnsordet 'tegnede'."},
{"l":4176,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om uret mangler et komma?","o":["På trods af uret kom vi til tiden.","Selvom uret gik forkert kom vi til tiden.","Uret gik forkert i går.","Alligevel kom vi til tiden."],"a":"Selvom uret gik forkert kom vi til tiden.","r":"'Selvom uret gik forkert' er en ledsætning, der står først. 'På trods af uret' ligner, men har intet udsagnsord."},
{"l":4194,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Kristian havde fået sin stil tilbage fra læreren, stod der kun: God idé, men læs den selv højt, før du afleverer. Han læste den højt for sig selv og opdagede tre steder, hvor han kom til at snuble over sine egne ord. Han satte sig ned og skrev dem om.' Hvad ville læreren med sin kommentar?","o":["At Kristian skulle øve sig i at tale højere i klassen","At Kristian skulle aflevere sin stil til en anden lærer","At Kristian selv skulle opdage, hvad der kunne blive bedre","At Kristian skulle holde op med at skrive om sine idéer"],"a":"At Kristian selv skulle opdage, hvad der kunne blive bedre","r":"Læreren peger ikke på fejlene, men giver en metode, så Kristian selv kan finde dem."},
{"l":4213,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er rigtigt? 'De to ___ deler værelse.'","o":["brødrer","brører","brøder","brødre"],"a":"brødre","r":"Flertal af 'bror' er uregelmæssigt. Det ender på -dre uden r til sidst."},
{"l":4232,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken lære har ordsproget 'Den, der graver en grav for andre, falder selv i den'?","o":["Den, der vil skade andre, ender med selv at blive ramt","Den, der arbejder i jorden, skal passe på, hvor han går","Den, der hjælper andre, får altid hjælp af dem igen","Den, der går alene om natten, kan let komme til skade"],"a":"Den, der vil skade andre, ender med selv at blive ramt","r":"Graven er en fælde. Ordsproget siger, at det onde, man finder på mod andre, kan vende tilbage mod en selv."},
{"l":4252,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilke to tegn mangler i: 'Da Yasmin kom ind i klassen spurgte læreren »Hvor har du været?«'?","o":["komma og punktum","komma og kolon","punktum og kolon","to kommaer"],"a":"komma og kolon","r":"Der skal komma efter ledsætningen, der slutter med 'klassen', og kolon efter 'læreren' foran den direkte tale."},
{"l":4270,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"I hvilken avistekst giver avisen selv sin mening til kende?","o":["en notits","en reportage","en leder","en vejrudsigt"],"a":"en leder","r":"Lederen er avisens egen holdning til en sag. En notits og en reportage skal derimod fortælle om det, der er sket."},
{"l":4295,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Kommunen vil indføre nye regler for cykelparkering. Hvad vil det sige at 'indføre' regler?","o":["holde op med at bruge dem","skrive dem af fra en bog","tale imod dem","begynde at bruge dem"],"a":"begynde at bruge dem","r":"Når man indfører noget, tager man det i brug for første gang. Her gælder reglerne altså fra nu af."},
{"l":4311,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'da' i sætningen: 'Da vi kom hjem, var det mørkt.'","o":["bindeord","biord","forholdsord","stedord"],"a":"bindeord","r":"'Da' indleder her en ledsætning, der siger, hvornår noget skete. Det er derfor et bindeord."},
{"l":4333,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'for' i sætningen: 'Jeg tog vanter på, for det var koldt.'","o":["forholdsord","bindeord","stedord","udsagnsord"],"a":"bindeord","r":"'For' binder to sætninger sammen og giver en grund. Her er det derfor et bindeord."},
{"l":4355,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad forstår man ved en 'fristelse'?","o":["noget, man er bange for at miste igen","noget, man har lovet at gøre for en anden","noget, man har lyst til, selv om man ikke bør","noget, man skal nå, før fristen er slut"],"a":"noget, man har lyst til, selv om man ikke bør","r":"En fristelse lokker en, for eksempel en kage lige før aftensmaden. Ordet har ikke noget med en frist at gøre."},
{"l":4370,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Teo sad i toget med høretelefonerne i ørerne. På sædet foran talte to mænd om fiskeri, og Teo, der elskede at fiske, slukkede stille for musikken, men lod høretelefonerne sidde. Da den ene sagde, hvor gedderne bed, skrev han det ned på sin mobil.' Hvorfor lod Teo høretelefonerne sidde?","o":["De skulle holde hans ører varme","Han ville høre musik igen om lidt","Han ville vise, at han kunne lide fisk","Mændene skulle ikke opdage, at han lyttede"],"a":"Mændene skulle ikke opdage, at han lyttede","r":"Musikken er slukket, men høretelefonerne bliver siddende. Så ligner det, at han hører musik, mens han i virkeligheden lytter til mændene."},
{"l":4393,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Skolebladet bringer et 'interview' med en forfatter. Hvad er det?","o":["en samtale, hvor én stiller spørgsmål til en anden","et billede, der følger med en artikel i bladet","en kort film, der reklamerer for en ny bog","et brev, som en læser har sendt til redaktionen"],"a":"en samtale, hvor én stiller spørgsmål til en anden","r":"I et interview spørger en journalist, og den interviewede svarer. Ordet er lånt fra engelsk."},
{"l":4410,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Når is smelter, optager den varme. Det er derfor, en isterning køler din saft. Isen tager varme fra saften, mens den smelter, og så bliver saften koldere. Kulde er altså ikke noget, der kommer ind. Det er varmen, der forsvinder.' Hvilket synspunkt prøver teksten at ændre?","o":["At is kan laves af almindeligt vand","At kulde er noget, der kommer ind i saften","At saft altid smager bedst med mange isterninger i","At is smelter hurtigere i koldt vand"],"a":"At kulde er noget, der kommer ind i saften","r":"Teksten forklarer, at det er varmen, der forsvinder. Den retter altså opfattelsen af kulde som noget, der kommer ind."},
{"l":4430,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Må jeg gå på ___ i timen?'","o":["toilett","tojlet","toilet","toalet"],"a":"toilet","r":"Ordet er fransk og ender på ét t. Vokalerne o og i står lige efter hinanden."},
{"l":4453,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad hedder den forsamling med 179 medlemmer, der vedtager Danmarks love?","o":["regeringen","byrådet","Højesteret","Folketinget"],"a":"Folketinget","r":"Folketinget vedtager lovene. Regeringen leder landet, og Højesteret er landets øverste domstol."},
{"l":4470,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der var hundrede trin op til fyrtårnet, og morfar stoppede på hvert tiende. Han sagde, at han ville se på udsigten. Der var ingen vinduer. Selma stoppede sammen med ham og lod, som om der var noget at se på væggen.' Hvad gør Selma, og hvorfor?","o":["Hun lader som ingenting, så morfar ikke bliver flov","Hun leder efter et vindue, fordi hun vil se ud","Hun er træt af trapperne og vil gerne hjem igen","Hun kigger efter malerier på væggen i fyrtårnet"],"a":"Hun lader som ingenting, så morfar ikke bliver flov","r":"Morfar skjuler, at han er forpustet. Selma forstår det og lader som ingenting, så han ikke bliver flov."},
{"l":4490,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Andreas og Lea diskuterede, hvem der havde ret, helt ned ad gaden. Andreas sagde, at han havde set bolden over linjen. Lea sagde, at han altid sagde sådan, når hans hold tabte. Hun sagde også, at han havde en dårlig frisure. Andreas gik ud fra, at det betød, at hun ikke havde flere argumenter.' Hvorfor tolker Andreas det sådan?","o":["Fordi Lea er bedre til at klippe hår end ham","Fordi frisuren ikke har noget med sagen at gøre","Fordi Lea havde ret i, at bolden var over linjen","Fordi han ved, at han altid taber, når de spiller"],"a":"Fordi frisuren ikke har noget med sagen at gøre","r":"Når man angriber en person i stedet for argumentet, er det tit, fordi man ikke har noget bedre at sige."},
{"l":4510,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fra næste år må der ikke længere stå sodavandsautomater på skolerne i Vestkommunen. Det har byrådet vedtaget efter klager fra mange forældre. Enkelte elever er utilfredse og har startet en underskriftindsamling. Skolelederne siger, at de vil følge beslutningen.' Hvem er imod den nye beslutning?","o":["Mange forældre i kommunen","Skolelederne i kommunen","Enkelte elever","Byrådet i Vestkommunen"],"a":"Enkelte elever","r":"Forældrene har klaget over automaterne, og skolelederne følger beslutningen. Kun eleverne samler underskrifter imod."},
{"l":4530,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'For hundrede år siden boede langt flere danskere på landet. I dag bor langt de fleste i byer. Mange unge flytter væk fra små byer for at uddanne sig, og kun få vender tilbage. Skoler og butikker lukker, fordi der er for få kunder og elever. Det får endnu flere til at flytte.' Hvad gør, at problemet bliver ved?","o":["At unge kommer hjem efter deres uddannelse","At byerne bygger for mange nye butikker","At danskerne hellere vil bo på landet end i byer","At der flytter flere, når skoler og butikker lukker"],"a":"At der flytter flere, når skoler og butikker lukker","r":"Når folk flytter, lukker skoler og butikker, og så flytter endnu flere. Sådan bliver det ved."},
{"l":4550,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form er den rigtige? 'To ___ byggede vores nye tag.'","o":["tømrere","tømrer","tømmerer","tømmere"],"a":"tømrere","r":"Der er to personer, så det er flertal på -ere. Ordet har kun ét m foran r."},
{"l":4574,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En tømrer og en murer er begge faglærte inden for byggeri. Hvad kaldes sådan en person? Vælg den rigtige stavning.","o":["hånværker","håndværker","håndværger","håndverker"],"a":"håndværker","r":"Ordet er sammensat af 'hånd' og 'værk' med endelsen -er. D'et er stumt, men det skal med."},
{"l":4589,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Mathilde 'gør en myg til en elefant'. Hvad gør hun?","o":["hun er bange for selv de mindste dyr","hun bliver stærkere af at træne hver dag","hun gør noget småt meget større, end det er","hun giver en ven en alt for stor gave"],"a":"hun gør noget småt meget større, end det er","r":"Talemåden bruges om at overdrive et lille problem, så det virker kæmpestort."},
{"l":4604,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad viser en taleboble med spidse, takkede kanter tit i en tegneserie?","o":["At personen sover","At personen hvisker","At personen tænker","At personen råber"],"a":"At personen råber","r":"Takkede kanter giver en voldsom virkning, som når nogen råber. Bobler med stiplet kant bruges tit, når nogen hvisker."},
{"l":4625,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lokalavisen skrev: Skolebestyrelsen vil lukke biblioteket. Dagen efter stod der med småt: Rettelse. Bestyrelsen vil flytte biblioteket til nye lokaler. Men da var der allerede kommet 60 vrede mails, og flere forældre havde delt den første artikel.' Hvad er tekstens pointe?","o":["At en forkert overskrift kan gøre skade, selv når den rettes","At lokalaviser ikke bør skrive om biblioteker","At forældre skriver flere mails end eleverne gør","At skolebestyrelsen ville lukke biblioteket i det skjulte"],"a":"At en forkert overskrift kan gøre skade, selv når den rettes","r":"Rettelsen er lille og kommer for sent. Vreden er allerede spredt. Det er tekstens pointe."},
{"l":4645,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jeg er træt af, at folk kalder unge for dovne. Min søster står op klokken fem for at gå med aviser, før hun skal i skole. Jeg passer min lillebror tre dage om ugen. De fleste af mine venner har fritidsjob. Så hvor er alle de dovne unge, jeg hører om?' Hvorfor stiller skribenten det sidste spørgsmål?","o":["Fordi skribenten gerne vil have et svar på det","For at vise, at det ikke passer, at unge er dovne","Fordi skribenten selv vil finde nogle af de dovne unge","For at spørge søsteren, hvad hun synes om det"],"a":"For at vise, at det ikke passer, at unge er dovne","r":"Det er et retorisk spørgsmål. Skribenten forventer ikke svar, men vil vise, at påstanden om dovne unge ikke holder."},
{"l":4664,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"I Danmark har vi 'ytringsfrihed'. Hvad betyder det?","o":["retten til at rejse, hvorhen man vil","retten til at gå i skole uden at betale","retten til at sige sin mening offentligt","retten til at holde fri hver søndag"],"a":"retten til at sige sin mening offentligt","r":"En ytring er noget, man siger eller skriver. Ytringsfrihed er friheden til at give sin mening til kende."},
{"l":4685,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hele udsagnsleddet: 'Vi skal male hegnet.'","o":["Vi","hegnet","male hegnet","skal male"],"a":"skal male","r":"'Skal' og 'male' hører sammen og fortæller tilsammen, hvad der skal ske. Derfor er begge ord med i udsagnsleddet."},
{"l":4700,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jeg er ikke bange for mørke. Jeg har bare altid en lampe tændt, en dør på klem og en radio, der hvisker.' Hvad skal læseren forstå?","o":["At fortælleren nok er mere bange, end det indrømmes","At fortælleren er træt af at høre radio om natten","At fortælleren har fået en ny lampe og radio","At fortælleren ikke kan sove uden en bog"],"a":"At fortælleren nok er mere bange, end det indrømmes","r":"Fortælleren benægter frygten, men vanerne røber den. Læseren skal tro på handlingerne frem for udsagnet."},
{"l":4718,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken tid står sætningen i: 'Bedstefar er rejst til Grønland.'","o":["nutid","førnutid","førdatid","datid"],"a":"førnutid","r":"'Er' plus tillægsform er førnutid, selv om sætningen ikke har 'har'. Nogle udsagnsord om bevægelse danner førnutid med 'er'."},
{"l":4739,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'tilbageholdende' om en person?","o":["genert","forsigtig","udadvendt","eftertænksom"],"a":"udadvendt","r":"Den tilbageholdende holder sig i baggrunden. Den udadvendte søger selv kontakt og taler gerne med andre."},
{"l":4755,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Regnskoven kaldes af og til for klodens lunger. Billedet er ikke helt rigtigt, for skoven forbruger selv næsten al den ilt, den laver. Men skoven gemmer enorme mængder kulstof. Når den bliver fældet og brændt, slipper kulstoffet ud i luften.' Hvad er det, teksten retter?","o":["At regnskoven er vigtig for klimaet","At regnskoven gemmer kulstof","At regnskoven bliver fældet og brændt","At regnskoven er vores største iltkilde"],"a":"At regnskoven er vores største iltkilde","r":"Teksten siger, at billedet med lungerne ikke holder, fordi skoven selv bruger ilten. Vigtigheden fastholder den."},
{"l":4777,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man noget, man siger er sandt, selv om det ikke er bevist?","o":["en påstand","en kendsgerning","en overskrift","en kvittering"],"a":"en påstand","r":"En påstand kan være sand eller falsk, men den skal undersøges. En kendsgerning er derimod noget, der er sikkert."},
{"l":4796,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Tænd ovnen på 200 grader. Pisk æg og sukker. Rør melet i.' Hvilken form har udsagnsordene i teksten?","o":["datid","bydeform","førnutid","navneform"],"a":"bydeform","r":"Tænd, pisk og rør er bydeform. Den er typisk for opskrifter, fordi teksten siger, hvad du skal gøre."},
{"l":4814,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Bilen kører på strøm, så den er ___.'","o":["elektrisg","eletrisk","elektrisk","elektris"],"a":"elektrisk","r":"Ordet har k foran t og ender på -isk."},
{"l":4835,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassen satte to ens bønneplanter i vindueskarmen. Den ene fik vand hver dag, den anden hver tredje dag. Efter to uger var den første gul og slap, mens den anden var grøn. Asta skrev i sin rapport: Alle planter skal vandes hver tredje dag.' Hvad er svagheden i Astas konklusion?","o":["Begge planter stod det samme sted i vindueskarmen","Den gule plante fik mindre vand end den grønne","Forsøget varede alt for længe til at vise en tydelig forskel","Hun siger noget om alle planter ud fra kun to bønner"],"a":"Hun siger noget om alle planter ud fra kun to bønner","r":"To bønneplanter kan ikke fortælle, hvad alle planter har brug for. At de stod samme sted, kan ligne en fejl, men det gør netop forsøget retfærdigt."},
{"l":4852,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'teoretisk' i udtrykket 'teoretisk viden'?","o":["praktisk","grundig","gammel","skriftlig"],"a":"praktisk","r":"Teoretisk viden har man fra bøger og forklaringer. Praktisk viden får man ved selv at gøre tingene."},
{"l":4872,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Den 8. marts 1994 blev det første nummer af et lokalt skoleblad trykt på Enghaveskolen. Bladet var skrevet af elever og handlede om livet på skolen. I dag, mere end 30 år senere, findes det stadig, men kun på nettet. Den nuværende redaktør er 14 år. Hun siger, at bladet har overlevet, fordi det altid har været de unge selv, der styrede det.' Hvad er redaktørens forklaring på, at bladet stadig findes?","o":["Bladet er kommet på nettet","Eleverne har selv styret det","Bladet er trykt på godt papir","Lærerne har hjulpet med det"],"a":"Eleverne har selv styret det","r":"Hun siger, at det altid har været de unge selv, der styrede bladet. Internettet er kun en af ændringerne undervejs."},
{"l":4892,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hele ugen fortalte Rasmus om den kæmpegedde, han havde fanget. Hver dag blev hans arme lidt længere, når han viste størrelsen. I fredags tog han billedet med i skole. Gedden var ikke meget længere end hans hånd.' Hvad viser det, at armene bliver længere?","o":["Han husker fisken mere og mere præcist for hver dag","Han vil vise klassen, hvordan man måler en gedde rigtigt","Han gør fisken større, hver gang han fortæller om den","Gedden var så stor, at den næsten ikke var til at holde"],"a":"Han gør fisken større, hver gang han fortæller om den","r":"Billedet afslører, at armene voksede, mens fisken forblev lille. Man kan tro, at han bare huskede bedre, men så ville målet ikke ændre sig hver dag."},
{"l":4912,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kære nabo. Vi har med glæde lyttet til din trommeøvelse hver aften i tre uger. Vi kender nu alle numre. Vi spekulerer på, om du kunne tænke dig at lære et nyt, eller eventuelt at spille før klokken 22? Venlig hilsen dine søvnløse naboer på 2. sal' Hvad er naboernes egentlige ærinde?","o":["At få trommeslageren til at lære flere numre","At spørge, om de selv kan spille med","At takke for gode oplevelser de sidste uger","At bede trommeslageren om at stoppe tidligere"],"a":"At bede trommeslageren om at stoppe tidligere","r":"Ordet 'søvnløse' og spørgsmålet om klokken 22 afslører, at brevet er en høflig, ironisk klage."},
{"l":4932,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alle i familien havde ønsket sig en hund, og nu var Bamse kommet. Han gøede ad støvsugeren og spiste en hjemmesko. Far sagde, at hunden skulle sove i bryggerset, og at det var hans sidste ord. Næste morgen lå Bamse i fars seng. Far påstod, at han ikke havde hørt noget.' Hvad fortæller den sidste sætning?","o":["At far ikke vil indrømme, at han lukkede hunden ind","At far sov så tungt, at han ikke opdagede hunden","At far er blevet vred på hunden i løbet af natten","At hunden selv har lært at åbne døren til bryggerset"],"a":"At far ikke vil indrømme, at han lukkede hunden ind","r":"Far havde sagt, at det var hans sidste ord, og nu ligger hunden i hans seng. Når han påstår, at han intet har hørt, er det en undskyldning."},
{"l":4950,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man en tegning, der med vilje overdriver en persons træk?","o":["portræt","karikatur","illustration","skitse"],"a":"karikatur","r":"En karikatur forstørrer for eksempel næse eller ører for at gøre tegningen sjov eller kritisk."},
{"l":4971,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vi så Alma og Jens ved søen. Hvilket ord passer: 'Vi hilste på ___.'","o":["de","deres","dem","sig"],"a":"dem","r":"Efter forholdsordet 'på' skal stedordet stå i den form, der hedder 'dem'. 'De' bruges som grundled."},
{"l":4992,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jeg har aldrig forstået, hvorfor folk siger, at vinteren er trist. Når sneen falder, bliver alting stille. Lyset er lavt og gyldent, og når du kommer ind, smager kakaoen bedre end nogensinde. Sommeren er for alle. Vinteren skal man have fortjent.' Hvad er forskellen på skribentens syn og det, folk siger?","o":["Skribenten mener, at vinteren er kortere end sommeren","Skribenten synes, at vinteren er for stille og mørk","Skribenten synes, at sommeren er bedre end vinteren","Skribenten synes, at vinteren er dejlig"],"a":"Skribenten synes, at vinteren er dejlig","r":"Folk finder vinteren trist, men skribenten fremhæver stilheden, lyset og kakaoen."},
{"l":5004,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at ville': 'Hun har altid ___ være dyrlæge.'","o":["villet","ville","vil","skulle"],"a":"villet","r":"'Har' kræver tillægsform. Af 'at ville' hedder den 'villet'."},
{"l":5025,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Aftalen er ___: Den gælder, og ingen af parterne kan trække sig.'","o":["foreløbig","bindende","frivillig","fleksibel"],"a":"bindende","r":"En bindende aftale forpligter dem, der har indgået den. Man kan ikke bare træde ud af den igen."},
{"l":5042,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sommetider er det bedste ved et kort, at det ikke passer. Da Silas og hans far fór vild på heden, fandt de en sø, der ikke var indtegnet. De spiste deres madpakker på bredden og så en odder. Far sagde: Vi skulle have været her for længst. Det var hans måde at sige, at det var den bedste tur nogensinde.' Hvad antyder tekstens første sætning?","o":["At kort ikke bør bruges af nogen, der vandrer","At de ikke fik det bedste kort med hjemmefra","At man kan få en god oplevelse, når man farer vild","At Silas’ far ikke kan finde vej på et kort"],"a":"At man kan få en god oplevelse, når man farer vild","r":"De farer vild og oplever noget uventet og godt. Det er det, første sætning peger frem mod."},
{"l":5062,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Spørgsmål til dyrlægen. Vores kat vil kun drikke vand fra hanen. Skal vi bekymre os? Svar: Nej. Katte foretrækker ofte rindende vand, måske fordi det i naturen er renere end stillestående. Prøv eventuelt en lille springvandsskål. Men hvis din kat pludselig drikker meget mere end før, skal du komme forbi.' Hvad er det, der er grund til at reagere på?","o":["At katten drikker vand fra hanen hver dag","At katten er glad for rindende vand","At katten ikke vil have en lille springvandsskål","At katten pludselig drikker meget mere end før"],"a":"At katten pludselig drikker meget mere end før","r":"Dyrlægen beroliger om vanen, men advarer om en pludselig ændring. Det er ændringen, der er vigtig."},
{"l":5082,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Spørgeskemaet, som blev sendt til eleverne, havde kun to svarmuligheder: Jeg er glad for skolen eller Jeg er meget glad for skolen. Da resultatet kom ud, skrev skolen stolt, at 100 procent af eleverne var glade. Nogen burde måske læse deres egen undersøgelse igen.' Hvad kritiserer skribenten?","o":["At man ikke kunne svare andet end, at man var glad","At eleverne ikke svarede ærligt på skemaet","At for få elever deltog i selve undersøgelsen","At skolen ikke sendte skemaet ud til alle forældrene"],"a":"At man ikke kunne svare andet end, at man var glad","r":"Når man kun kan svare, at man er glad, siger resultatet ikke noget. Svaret var givet på forhånd."},
{"l":5103,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at bringe': 'Postbuddet har ___ en pakke til nabohuset.'","o":["bragte","bragt","bringer","bringe"],"a":"bragt","r":"Efter 'har' står tillægsformen 'bragt'. 'Bragte' er datid."},
{"l":5125,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at bryde': 'Isbryderen har ___ isen i havnen.'","o":["brød","bryder","brudt","bryde"],"a":"brudt","r":"'At bryde' bøjes bryder, brød, har brudt. Efter 'har' står tillægsformen."},
{"l":5145,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der altid stå komma: 'Den pige der sidder ved vinduet hedder Asta.'?","o":["sidder","hedder","ved","vinduet"],"a":"vinduet","r":"Den indskudte ledsætning 'der sidder ved vinduet' slutter efter 'vinduet', og så skal der komma."},
{"l":5162,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Rummet ___ mig mere end noget andet.'","o":["interesserer","interessere","intresserer","interesseret"],"a":"interesserer","r":"Ordet står i nutid med -erer. Der er dobbelt s og e efter t."},
{"l":5182,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'uundværlig'?","o":["noget, man ikke kan undgå","noget, man ikke kan klare sig uden","noget, man slet ikke kan forstå meningen med","noget, man ikke kan betale"],"a":"noget, man ikke kan klare sig uden","r":"Det, der ikke kan undværes, er uundværligt. Pas på ikke at blande ordet sammen med 'uundgåelig'."},
{"l":5201,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det indirekte objekt: 'Karla lånte sin veninde en blyant.'","o":["en blyant","Karla","sin veninde","lånte"],"a":"sin veninde","r":"Indirekte objekt er det samme som hensynsled. Veninden er den, der får blyanten at låne."},
{"l":5222,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken form passer? 'Læreren ___ forsøget ved katederet, før vi selv prøver.'","o":["demonstrere","demonstreret","demonsterer","demonstrerer"],"a":"demonstrerer","r":"Ordet har r efter t. Nutid ender på -erer."},
{"l":5242,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'nostalgi'?","o":["længsel efter noget, der er forbi","angst for det, der skal komme","glæde over noget helt nyt","vrede over en uretfærdighed"],"a":"længsel efter noget, der er forbi","r":"Nostalgi er, når man savner noget fra før, for eksempel barndommens somre."},
{"l":5259,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når Nadia bliver tiltalt til sidst?","o":["Du må gerne, låne mit viskelæder Nadia.","Du må gerne låne mit viskelæder, Nadia.","Du må, gerne låne mit viskelæder Nadia.","Du, må gerne låne mit viskelæder Nadia."],"a":"Du må gerne låne mit viskelæder, Nadia.","r":"Tiltale skilles fra sætningen med komma, også når navnet står til sidst."},
{"l":5280,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'bestikkelse'?","o":["at låne penge uden at betale dem tilbage igen","at sælge varer uden at have lov af kommunen","at give penge for at få en særlig fordel af nogen","at få andre til at fortælle en hemmelighed"],"a":"at give penge for at få en særlig fordel af nogen","r":"Bestikkelse er ulovligt: Man betaler for eksempel en embedsmand for at få en fordel, man ikke har ret til."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvor mange ledsætninger er der i: 'Jeg tror, at hun kommer, hvis hun kan.'","o":["én","tre","fire","to"],"a":"to","r":"'At hun kommer' og 'hvis hun kan' er ledsætninger. 'Jeg tror' er hovedsætningen."},
{"l":5310,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Efter kritikken måtte ministeren 'trække i land'. Hvad betyder det?","o":["at trække sine ord delvist tilbage","at tage hjem fra sin ferie ved havet","at forlade sin stilling i regeringen","at gentage sine ord endnu højere"],"a":"at trække sine ord delvist tilbage","r":"Den, der trækker i land, siger, at det ikke var helt så stærkt ment, for eksempel fordi andre har sagt imod."},
{"l":5330,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Der er en ___ forskel på de to bøger.'","o":["væsenlig","væsentlig","væsentli","vesentlig"],"a":"væsentlig","r":"Ordet staves med æ og har et t foran -lig, selvom det ikke høres."},
{"l":5347,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at to synspunkter er 'uforenelige'?","o":["at de er uklare og svære at forstå","at de ligner hinanden meget","at de ikke kan passe sammen","at de ikke bliver sagt højt"],"a":"at de ikke kan passe sammen","r":"Det, der kan forenes, kan samles. Uforenelige synspunkter kan ikke gælde på samme tid."},
{"l":5366,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Vi mødtes helt ___ i supermarkedet.'","o":["tilfælligt","tilfældit","tillfældigt","tilfældigt"],"a":"tilfældigt","r":"Ordet har ét l i 'til' og d foran -igt. D'et kan høres, men g'et kan ikke."},
{"l":5390,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes digte uden fast rim og uden fast rytme?","o":["frie vers","sonetter","limericks","remser"],"a":"frie vers","r":"Frie vers følger ikke faste regler for rim og rytme. Sonetter og limericks har derimod en fast form."},
{"l":5406,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skoletasken vejer for meget, hører man. Læger siger, at en taske højst bør veje en tiendedel af barnets vægt. Vi vejede tasker i 6.C. Den tungeste vejede 9 kilo, og ejeren vejer 45. I gennemsnit lå vi lige på grænsen.' Hvad kan man udlede om den tungeste taske?","o":["At den vejede lige præcis det anbefalede","At den vejede dobbelt så meget som anbefalet","At den vejede mindre end gennemsnittet","At den vejede en tiendedel af ejerens vægt"],"a":"At den vejede dobbelt så meget som anbefalet","r":"En tiendedel af 45 kilo er 4,5 kilo. Tasken vejede 9 kilo, altså det dobbelte."},
{"l":5426,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg den rigtige skrivemåde: 'Nu går vi ___ med opgaven.'","o":["igang","i gangg","i gang","i kang"],"a":"i gang","r":"Vendingen skrives i to ord, selvom den udtales som ét."},
{"l":5446,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Jobbet som dommer giver stor 'prestige'. Hvad betyder det?","o":["at man får meget høj løn for det hver måned","at man bliver træt af det","at man lærer meget af det","at folk ser op til en for det"],"a":"at folk ser op til en for det","r":"Prestige er den respekt, som andre har for en stilling eller en person."},
{"l":5465,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'bag' i: 'Bag en kage til i morgen!'","o":["udsagnsord","forholdsord","navneord","biord"],"a":"udsagnsord","r":"Sætningen er en opfordring, så 'bag' er bydemåde af 'at bage'. Det ligner forholdsordet 'bag', men her er det et udsagnsord."},
{"l":5486,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavningen: 'Den franske ___ begyndte i 1789.'","o":["revulution","revolution","revolusjon","refolution"],"a":"revolution","r":"Ordet har o efter v og u efter l, og det ender på -tion."},
{"l":5506,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hatten tilhører Agnes. Hvilken sætning er rigtig?","o":["Agnes's hat blæste af.","Agne's hat blæste af.","Agnes' hat blæste af.","Agnes hat blæste af."],"a":"Agnes' hat blæste af.","r":"Agnes ender på s, så ejefaldet vises med en apostrof efter navnet. Uden den ligner det ikke ejefald."},
{"l":5522,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'I et ___ kan man se stjernehimlen på et stort loft.'","o":["planatarium","planetariom","planettarium","planetarium"],"a":"planetarium","r":"Ordet kommer af 'planet' og ender på -arium."},
{"l":5543,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'eufemisme'?","o":["et mildere ord for noget ubehageligt","et grimt skældsord, som man bruger om en anden person","et ord lånt fra et andet sprog","et ord med flere betydninger"],"a":"et mildere ord for noget ubehageligt","r":"Når man siger 'det lille hus' i stedet for 'toilet', er det en eufemisme. Ordet lyder pænere."},
{"l":5563,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning har kommaet rigtigt, når 'for' binder to hovedsætninger sammen?","o":["Vi tog jakker, på for det blæste meget.","Vi tog jakker på, for det blæste meget.","Vi tog jakker på for, det blæste meget.","Vi tog, jakker på for det blæste meget."],"a":"Vi tog jakker på, for det blæste meget.","r":"Mellem to hovedsætninger står kommaet foran bindeordet, her 'for'."},
{"l":5582,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn skaber en lille pause før overraskelsen: 'Hun åbnede kassen ___ den var tom.'?","o":["apostrof","bindestreg","tankestreg","anførselstegn"],"a":"tankestreg","r":"Tankestregen giver en pause og gør læseren spændt på det, der kommer."},
{"l":5602,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi kalder det at have en mening. Men tit har vi den, før vi har tænkt over tingene. Prøv at spørge dig selv: Hvad skulle der til, for at jeg skiftede mening? Hvis svaret er intet, så er det ikke en mening, du har. Så er det en mening, der har dig.' Hvad betyder den sidste sætning?","o":["At man bør skifte mening mindst en gang om året","At man skal fortælle andre om sine meninger hver dag","At andre mennesker har ret til at bestemme ens mening","At man ikke længere selv tænker over sin mening"],"a":"At man ikke længere selv tænker over sin mening","r":"Hvis intet kan ændre din mening, styrer den dig i stedet for omvendt. Du er holdt op med at tænke over den."},
{"l":5620,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hamza råber en advarsel. Hvilken sætning er rigtig?","o":["»Pas på bolden!« råbte Hamza.","»Pas på bolden«! råbte Hamza.","»Pas på bolden! råbte Hamza.","Pas på bolden!« råbte »Hamza."],"a":"»Pas på bolden!« råbte Hamza.","r":"Udråbstegnet hører til replikken og står inden for anførselstegnene, og der skal ikke komma efter det."},
{"l":5641,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg det rigtige udsagnsled: 'Hun fandt sin nøgle i den jakke, hun ___ dagen før.'","o":["har haft på","havde haft på","har på","have haft på"],"a":"havde haft på","r":"'Fandt' er datid, og jakken blev brugt før det. Derfor står den tidligste handling i førdatid."},
{"l":5662,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Der var en mand, som hver vinterdag gik på vandet. En dag spurgte en dreng: Hvordan gør du? Manden svarede: Jeg venter, til isen er tyk nok. Drengen blev skuffet. Han havde håbet på noget magisk. Men manden sagde: Det er magisk nok at vide, hvornår man skal vente.' Hvad mener manden?","o":["At man kan gå på vandet, hvis man tror nok på det","At isen er blevet tykkere end før, på grund af vejret","At det er lige så godt som magi at vide, hvornår man skal vente","At drengen er for ung til at gå på isen om vinteren"],"a":"At det er lige så godt som magi at vide, hvornår man skal vente","r":"Drengen håbede på magi, men manden venter bare, til isen er tyk nok. Det er kunsten."},
{"l":5678,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord er stavet rigtigt? 'Hun går til ___ og øver sig på tåspids.'","o":["balet","ballett","balett","ballet"],"a":"ballet","r":"Ordet er fransk og har dobbelt l og kun ét t til sidst."},
{"l":5702,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvad er en god historie? Min farmor mente, at det var en, man kunne fortælle igen. Min lærer mener, at det er en, der har en begyndelse og en slutning. Min lillebror mener, at det er en, der indeholder en drage. Jeg er kommet til den konklusion, at de alle sammen har ret, men at min lillebror har mest ret.' Hvad er tonen i slutningen?","o":["Lun og humoristisk","Bitter og anklagende","Formel og belærende","Bange og usikker"],"a":"Lun og humoristisk","r":"Skribenten ender med at give lillebroren mest ret, og det er sagt med et smil. Tonen er venlig og sjov."},
{"l":5720,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Kira blev nummer ___ i løbet og fik lige akkurat ingen medalje.'","o":["fjere","fjerde","fjærde","fjerd"],"a":"fjerde","r":"Ordenstallet skrives med j og et stumt d, som man ikke kan høre: f-j-e-r-d-e."},
{"l":5740,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå, når to hovedsætninger bindes sammen: 'Regnen silede ned og vi løb ind i klubhuset.'?","o":["Regnen","vi","ned","løb"],"a":"ned","r":"Begge sætninger har eget grundled, 'regnen' og 'vi'. Derfor står kommaet foran 'og', altså efter 'ned'."},
{"l":5760,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Søjlediagrammet viser, hvor mange elever der cykler til Engskolen. I september cykler 210, i november 140 og i januar 60. I marts er tallet igen oppe på 150.' Hvilken påstand kan tallene ikke bevise?","o":["At færre cykler i januar end i november","At tallet stiger igen fra januar til marts","At over 200 elever cykler i september","At kulden er årsagen til faldet i januar"],"a":"At kulden er årsagen til faldet i januar","r":"Tallene viser, hvor mange der cykler, men ikke hvorfor. Kulde er et godt gæt, men det står ikke i diagrammet."},
{"l":5783,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er opgaven for en 'redaktør' på en avis?","o":["at bestemme, hvad avisen skal bringe","at trykke avisen på papir","at bringe avisen ud til læserne","at sælge annoncer til firmaer i byen"],"a":"at bestemme, hvad avisen skal bringe","r":"Redaktøren udvælger stoffet og har ansvaret for indholdet. Journalisterne skriver, og redaktøren beslutter, hvad der kommer med."},
{"l":5800,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Han sagde, at han var ligeglad. Han sagde det til sin taske, til sine sko og til væggen bag læreren.' Hvad viser sætningen?","o":["At han taler højt med sig selv","At han ikke kan se læreren i øjnene","At han er ligeglad med alt","At han leder efter sine sko"],"a":"At han ikke kan se læreren i øjnene","r":"Han kigger alle andre steder end på læreren. Det viser, at han ikke er så ligeglad, som han siger."},
{"l":5820,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort i spørgsmålet 'Har i lavet jeres lektier?'","o":["jeres","lektier","i","lavet"],"a":"i","r":"Stedordet I skrives altid med stort, så det ikke forveksles med forholdsordet 'i'. 'Jeres' skrives med lille."},
{"l":5837,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Før køleskabet gemte man ofte mad ved at salte eller tørre den. Begge dele fjerner det vand, som bakterier har brug for. Derfor kunne fisk holde sig hele vinteren.' Hvad tager forklaringen for givet uden at sige det?","o":["At saltet mad smager bedre end frisk mad","At folk dengang spiste mest fisk om vinteren","At køleskabet blev opfundet om vinteren","At bakterier får maden til at blive dårlig"],"a":"At bakterier får maden til at blive dårlig","r":"'Derfor' giver kun mening, hvis bakterier ødelægger maden. Det står ikke direkte, men forklaringen bygger på det."},
{"l":5859,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lagkagediagrammet viser, hvad 7.b bruger lommepenge på. Slik og snacks fylder 40 procent, tøj 25 procent og spil 20 procent. Resten bliver sparet op.' Hvilket udsagn passer med diagrammet?","o":["Opsparingen fylder mindre end spil","Over halvdelen går til slik og snacks","Spil fylder mere end tøj","Opsparingen er den næststørste post"],"a":"Opsparingen fylder mindre end spil","r":"Resten er 100 minus 85, altså 15 procent. Det er mindre end de 20 procent til spil."},
{"l":5881,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find det indirekte objekt (hensynsleddet): 'Noah gav sin søster en bog.'","o":["Noah","sin søster","gav","en bog"],"a":"sin søster","r":"Hensynsleddet er den, der får eller har gavn af noget. 'En bog' er det, der bliver givet, og det er genstandsleddet."},
{"l":5900,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ifølge uofficielle kilder har bestyrelsen muligvis drøftet et salg af hallen.' Hvilke ord gør oplysningen særligt usikker?","o":["Bestyrelsen og salg","Drøftet og hallen","Uofficielle og muligvis","Kilder og bestyrelsen"],"a":"Uofficielle og muligvis","r":"Ordene viser, at kilden ikke er bekræftet, og at det ikke er sikkert, hvad der er sket. Den slags ord kaldes forbehold."},
{"l":5918,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket tillægsord er dannet af navneordet 'ansvar'?","o":["ansvaret","ansvarlighed","ansvarsfølelse","ansvarlig"],"a":"ansvarlig","r":"Endelsen -lig laver mange navneord om til tillægsord. 'Ansvarlighed' og 'ansvarsfølelse' er stadig navneord."},
{"l":5940,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning skriver kongenavnet rigtigt?","o":["Kong Christian 4. byggede Rundetårn.","Kong Christian 4, byggede Rundetårn.","Kong Christian 4' byggede Rundetårn.","Kong Christian 4: byggede Rundetårn."],"a":"Kong Christian 4. byggede Rundetårn.","r":"Tallet læses 'den fjerde' og er et ordenstal, så det skal have punktum."},
{"l":5958,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi har prøvet at spise frokost udenfor hver fredag i et halvt år. Sygefraværet i klassen er faldet. Altså gør frisk luft os raskere.' Hvad er svagheden i argumentet?","o":["Et halvt år er for lang tid til at måle noget","Andre ting kan også have sænket sygefraværet","Frisk luft er ikke sundt om vinteren","Klassen burde spise frokost indenfor"],"a":"Andre ting kan også have sænket sygefraværet","r":"To ting, der sker samtidig, behøver ikke at hænge sammen. Årstid eller noget helt tredje kan være den egentlige årsag."},
{"l":5980,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ledsætning har rigtig ordstilling: 'Jeg bliver skuffet, …'?","o":["hvis du kommer ikke","hvis kommer du ikke","hvis du ikke kommer","hvis kommer ikke du"],"a":"hvis du ikke kommer","r":"I en ledsætning står 'ikke' foran verbet. I en hovedsætning står det efter: 'Du kommer ikke.'"},
{"l":6000,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hun så manden med kikkerten.' Hvilke to meninger kan sætningen have?","o":["Hun så manden, eller også så hun en anden mand","Manden så hende, eller også så hun manden i går","Kikkerten var gammel, eller også var den ny og dyr","Hun brugte kikkerten, eller også havde manden den"],"a":"Hun brugte kikkerten, eller også havde manden den","r":"'Med kikkerten' kan knytte sig til både 'så' og 'manden'. Det er et klassisk eksempel på en tvetydig sætning."},
{"l":6008,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'podcast'?","o":["et lydprogram, man kan høre, når man vil","en lille film, der kun varer ti sekunder","en besked, man sender fra sin telefon","en radiokanal, der sender hele døgnet"],"a":"et lydprogram, man kan høre, når man vil","r":"En podcast er et program, man henter på nettet og lytter til, når det passer en."},
{"l":6032,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken form passer? 'Postbuddet har ___ en pakke til dig.'","o":["brakt","bragt","bringt","brangt"],"a":"bragt","r":"Tillægsformen af 'bringe' skrives med a og g: bringe, bragte, bragt."},
{"l":6053,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I samfundsfag taler man om 'integration'. Hvad handler det om?","o":["at alle indbyggere flytter til de store byer","at landets grænser flyttes efter en aftale","at nye borgere bliver en del af fællesskabet","at nye borgere får lov til at komme ind i landet"],"a":"at nye borgere bliver en del af fællesskabet","r":"At integrere betyder at gøre noget til en del af en helhed. I samfundet handler det om at deltage i for eksempel skole, arbejde og foreningsliv."},
{"l":6071,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Opgaven ___ ro, selvom der er larm omkring os.'","o":["kræve","krævver","kræverer","kræver"],"a":"kræver","r":"Ordet er udsagnsled i nutid, så der skal r på: opgaven kræver."},
{"l":6091,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En journalist skriver en 'reportage'. Hvad er det særlige ved den genre?","o":["den tager læseren med ud, hvor det sker","den giver avisens egen mening om en vigtig sag","den vurderer en film eller en bog med stjerner","den bringer korte fakta om vejret og trafikken"],"a":"den tager læseren med ud, hvor det sker","r":"Journalisten er selv på stedet og fortæller, hvad der kan ses og høres. Avisens mening står i lederen, og vurderinger står i anmeldelser."},
{"l":6106,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et tv-program laver 'satire' over kendte politikere. Hvad gør programmet?","o":["følger dem for at skrive deres livshistorie","gør grin med dem for at kritisere dem","hjælper dem med at vinde et valg","interviewer dem om deres barndom"],"a":"gør grin med dem for at kritisere dem","r":"Satire bruger humor og overdrivelse til at pege på fejl og svagheder. Det er altså både sjovt og kritisk."},
{"l":6124,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes det sted i en fortælling, hvor spændingen er allerhøjest?","o":["anslag","udtoning","klimaks","præsentation"],"a":"klimaks","r":"Klimaks er højdepunktet, hvor konflikten topper. Bagefter falder spændingen i udtoningen."},
{"l":6145,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hans Ole, 13, ejer tre fiskestænger og har fanget 214 fisk. Han skriver alle sine fangster ned i et hæfte. I går tog han hæftet med i skole.' Hvad står der ikke noget om?","o":["Hvor mange fiskestænger han har","Hvor gammel Hans Ole er","Hvad han skriver i sit hæfte","Hvad klassen sagde til hæftet"],"a":"Hvad klassen sagde til hæftet","r":"Teksten fortæller, at hæftet kom med i skole, men slutter dér. Reaktionen må man selv forestille sig."},
{"l":6166,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Lægen foretog en undersøgelse.' Hvilket hverdagsord kan erstatte 'foretog'?","o":["lavede","aflyste","betalte","glemte"],"a":"lavede","r":"'Foretage' er et formelt ord for at udføre eller lave noget. Det bruges især i skriftsprog."},
{"l":6188,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Når du låner penge i banken, skal du betale 'rente'. Hvad er det?","o":["det beløb, du oprindeligt har lånt","betaling for at låne penge i et stykke tid","det gebyr, du betaler for at lukke kontoen","den skat, staten tager af din løn"],"a":"betaling for at låne penge i et stykke tid","r":"Renten er prisen for at låne. Beløbet, man har lånt, hedder hovedstolen, og det skal betales tilbage oven i renten."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skemaet viser, at skolens solceller gav 200 kWh i januar og 1.600 kWh i juli. Skolens eget elforbrug var størst i januar og mindst i juli, hvor skolen er lukket.' Hvad er ulempen, som skemaet afslører?","o":["Solcellerne giver mest strøm om vinteren","Skolen bruger mere strøm i juli end i januar","Solcellerne giver meget strøm, når skolen bruger lidt","Elforbruget er det samme året rundt på skolen"],"a":"Solcellerne giver meget strøm, når skolen bruger lidt","r":"Solcellerne giver mest strøm i juli, hvor skolen er lukket, og mindst i januar, hvor skolen bruger mest. Det ser man kun ved at holde tallene op mod hinanden."},
{"l":6220,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvor skal kommaet stå i spørgsmålet 'Hvis du får tid vil du så ringe til mig?'","o":["efter du","efter så","efter ringe","efter tid"],"a":"efter tid","r":"Spørgsmålet begynder med ledsætningen 'Hvis du får tid', så kommaet skal stå efter 'tid'."},
{"l":6240,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken form er rigtig i bestemt form: 'Vi så fodbold i ___ i går aftes.'?","o":["tv'et","tv:et","t.v.et","tv,et"],"a":"tv'et","r":"Tv er en forkortelse, og når den bøjes, kommer der apostrof foran endelsen."},
{"l":6260,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning om Sofies hund har parentesen og punktummet rigtigt?","o":["Sofie tog hunden med. (den hedder Bella).","Sofie tog hunden med (den hedder Bella).","Sofie tog hunden (med den hedder Bella).","Sofie tog hunden med (den hedder, Bella)."],"a":"Sofie tog hunden med (den hedder Bella).","r":"Parentesen er en del af sætningen, så sætningens punktum står efter parentesen."},
{"l":6280,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Hver tirsdag spiser vi pizza på grønnegade sammen med vores nye naboer.'?","o":["tirsdag","pizza","grønnegade","naboer"],"a":"grønnegade","r":"Vejnavne er egennavne og skrives med stort. Ugedage skrives med lille."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Min bedstefar cyklede uden hjelm hele sit liv og blev 92 år. Så snak om, at hjelme er nødvendige.' Hvad er svagheden i argumentet?","o":["Bedstefaren har ikke oplyst, hvilken slags cykel han kørte på","Hjelme var slet ikke opfundet, da bedstefaren levede","Argumentet nævner ikke, hvor mange år han cyklede","Ét tilfælde siger ikke noget om risikoen for alle andre"],"a":"Ét tilfælde siger ikke noget om risikoen for alle andre","r":"Et enkelt heldigt eksempel beviser ikke, at noget er ufarligt. Det er generalisering ud fra ét tilfælde."},
{"l":6312,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sætningsled er 'meget stolt' i: 'Zainab blev meget stolt.'?","o":["omsagnsled","genstandsled","hensynsled","grundled"],"a":"omsagnsled","r":"'Meget stolt' beskriver grundleddet Zainab efter verbet 'blive'. Derfor er det et omsagnsled."},
{"l":6334,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er et biord (adverbium) i: 'Vi kommer måske til Bornholm næste år.'?","o":["Vi","måske","kommer","Bornholm"],"a":"måske","r":"'Måske' fortæller noget om, hvor sikkert det er, at vi kommer. Det er et typisk biord."},
{"l":6356,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken verbalform gør sætningen passiv: 'Avisen ___ ud hver morgen klokken seks.'?","o":["bringer","bragte","bringes","bringe"],"a":"bringes","r":"S-formen 'bringes' giver passiv: Nogen bringer avisen, men vi får ikke at vide hvem."},
{"l":6378,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Vi aflyste turen, fordi bussen var gået i stykker.'?","o":["tid","betingelse","indrømmelse","årsag"],"a":"årsag","r":"'Fordi' svarer på spørgsmålet hvorfor. Ledsætningen angiver altså årsagen til, at turen blev aflyst."},
{"l":6398,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et parti kom ikke over 'spærregrænsen'. Hvad betyder det?","o":["det fik for få stemmer til Folketinget","det har brugt for mange penge på valgkampen","det har stillet for mange kandidater op","det må ikke være med i en regering"],"a":"det fik for få stemmer til Folketinget","r":"I Danmark skal et parti som hovedregel have mindst 2 procent af stemmerne for at komme i Folketinget."},
{"l":6413,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en målgruppe?","o":["De personer, der medvirker på reklamens billede","De personer, afsenderen især vil nå med sin tekst","De personer, der er ansat hos den, som sælger varen","De personer, der selv har skrevet hele reklamen"],"a":"De personer, afsenderen især vil nå med sin tekst","r":"Målgruppen er dem, teksten er rettet mod, f.eks. unge eller børnefamilier. Afsenderen tilpasser ord og billeder til dem."},
{"l":6435,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Frugt og motion er godt for din ___.'","o":["sunhed","sundhet","sundhed","sunnhed"],"a":"sundhed","r":"Ordet består af 'sund' og endelsen '-hed'. D'et i 'sund' bliver stående."},
{"l":6458,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en opgave står der: 'Redegør for årsagerne til krigen.' Hvad skal du gøre?","o":["diskutere, om årsagerne var gode eller dårlige","skrive din egen mening om krigen","gætte på, hvad der ville ske bagefter","forklare klart, hvad årsagerne var"],"a":"forklare klart, hvad årsagerne var","r":"At redegøre er at gøre rede for noget, altså at forklare fakta uden at bedømme dem. At diskutere eller vurdere kommer først bagefter."},
{"l":6480,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord kræves der komma: 'Hun kunne ikke sove fordi hun var nervøs men hun sagde ingenting.'?","o":["nervøs","kunne","men","sagde"],"a":"nervøs","r":"Ledsætningen slutter efter 'nervøs', og foran 'men' skal der komma. Begge dele peger på samme sted."},
{"l":6499,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Pigerne hjælper hver den anden. Hvilket stedord skal stå: 'Asta og Alma hjalp ___ med lektierne.'?","o":["sig","hinanden","dem","os"],"a":"hinanden","r":"'Hinanden' er et gensidigt stedord: Handlingen går begge veje. 'Dem' ville betyde nogle andre personer."},
{"l":6510,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå: 'Drengen, ___ cykel blev stjålet, gik til politiet.'?","o":["hvilken","som","hvis","der"],"a":"hvis","r":"'Hvis cykel' betyder her 'hans cykel', så 'hvis' viser, hvem noget tilhører. 'Som' og 'der' kan ikke vise ejerskab."},
{"l":6530,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I årevis havde Viktor drømt om at finde nøglen til loftet. Nu stod han i det mørke trappehul og drejede. Den passede. Det var det værste ved det hele.' Hvad gør den sidste sætning ved læseren?","o":["Den gør det klart, at Viktor var på det forkerte loft","Den forklarer, hvem der havde gemt nøglen","Den afslutter spændingen med en god løsning","Den gør læseren nysgerrig på, hvad der venter"],"a":"Den gør læseren nysgerrig på, hvad der venter","r":"Det, han har drømt om, er pludselig 'det værste'. Det gør os spændte, fordi vi endnu ikke ved hvorfor."},
{"l":6549,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad betyder det, at et digt er skrevet på frie vers?","o":["Det har hverken fast rim eller fast rytme","Det må læses af alle uden at betale for det","Det har altid præcis fire linjer i hver strofe","Det handler om frihed og er skrevet i krigstid"],"a":"Det har hverken fast rim eller fast rytme","r":"Frie vers følger ikke faste regler for rim og rytme. Digteren bestemmer selv linjernes længde."},
{"l":6566,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad betyder det, at en novelle har en åben slutning?","o":["Læseren får at vide præcis, hvordan alt ender","Læseren selv må tænke, hvordan det går videre","Alle personer samles til en stor fest til sidst","Slutningen fortæller, hvad der skete i starten"],"a":"Læseren selv må tænke, hvordan det går videre","r":"En åben slutning giver ikke et endeligt svar. Læseren må selv overveje, hvad der sker bagefter."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
